export default async function prepare({ body, acknowledge }, ctx) {
  const s = await ctx.state.get("nostr-report");
  if (s?.pending) {
    if (acknowledge !== s.pending)
      throw Error("Reconcile pending Nostr report " + s.pending + " before continuing");
    await ctx.state.set("nostr-report", null);
  }
  if (
    !Array.isArray(body.events) ||
    !body.events.length ||
    body.events.some((x) => typeof x.content !== "string")
  )
    throw Error("Nostr relay must provide events with content");
  return {
    content: JSON.stringify(body.events.map((x) => x.content)),
    runId: String(body.runId || ""),
  };
}

